// Runs the edge cases of test/cases/parse-cases.mts: their results are snapshotted in parse-snapshot.json, and compared
// to the results of real JVMs (parse-expected.json, generated by tools/gen-parse-expected.mts).
import {describe, expect, it} from 'vitest';
import {parse} from '../../src/java-props';
import cases from '../cases/parse-cases.mts';
import {readParseExpected} from '../support/data.mts';
import {captureLoad, LOAD_ERAS, type LoadEra, type LoadResult} from '../support/load-result.mts';

const expected = readParseExpected();
const results: Record<string, LoadResult> = {};
for (const c of cases) results[c.name] = captureLoad(() => parse(c.input));

// Cases where parse() differs from Java, kept on purpose so that existing code keeps working.
// Exception classes are not compared (Error vs IllegalArgumentException).
const JAVA_DIVERGENCES: Record<LoadEra, string[]> = {
    jdk8: [
        'lone continuation backslash: alone',
        'lone continuation backslash: alone with LF',
        'lone continuation backslash: after property',
        'lone continuation backslash: after property, with LF',
        'lone continuation backslash: indented',
        'comment ending with backslash, then backslashes: comment ending with backslash, then backslash-only line',
        'comment ending with backslash, then backslashes: bang comment, CRLF, lone backslash',
        'comment ending with backslash, then backslashes: comment with 3 backslashes, then backslashes',
        'stale line buffer: lone backslash decode after comment',
        'stale line buffer: truncated unicode after longer line',
    ],
    jdk11: [
        'lone continuation backslash: alone',
        'lone continuation backslash: alone with LF',
        'lone continuation backslash: after property',
        'lone continuation backslash: after property, with LF',
        'lone continuation backslash: indented',
        'empty continuation then comment char: hash',
        'empty continuation then comment char: bang with indentation',
        'empty continuation then comment char: hash after CRLF',
        'empty continuation then comment char: hash with leading whitespace on next line',
        'empty continuation then comment char: double continuation then hash',
        'comment ending with backslash, then backslashes: comment ending with backslash, then backslash-only line',
        'comment ending with backslash, then backslashes: comment with 3 backslashes, then backslashes',
        'stale line buffer: truncated unicode after longer line',
    ],
    jdk13: [
        'lone continuation backslash: alone',
        'lone continuation backslash: alone with LF',
        'lone continuation backslash: after property',
        'lone continuation backslash: after property, with LF',
        'lone continuation backslash: indented',
        'empty continuation then comment char: hash',
        'empty continuation then comment char: bang with indentation',
        'empty continuation then comment char: hash after CRLF',
        'empty continuation then comment char: hash with leading whitespace on next line',
        'empty continuation then comment char: double continuation then hash',
        'comment ending with backslash, then backslashes: comment ending with backslash, then backslash-only line',
        'comment ending with backslash, then backslashes: comment with 3 backslashes, then backslashes',
    ],
};

const sameOutcome = (a: LoadResult, b: LoadResult) => {
    if ('throws' in a || 'throws' in b) return 'throws' in a && 'throws' in b && a.message === b.message;
    return JSON.stringify(Object.entries(a.props).sort()) === JSON.stringify(Object.entries(b.props).sort());
};

describe('parse cases', () => {
    it('match the snapshot', async () => {
        const snapshot = Object.fromEntries(cases.map((c) => [c.name, {input: c.input, ...results[c.name]}]));
        await expect(`${JSON.stringify(snapshot, null, 2)}\n`).toMatchFileSnapshot('../cases/parse-snapshot.json');
    });

    it('all have Java results', () => {
        expect(Object.keys(expected).sort()).toEqual(cases.map((c) => c.name).sort());
    });

    for (const era of LOAD_ERAS) {
        it(`only diverge from Java (${era}) on the known cases`, () => {
            const divergences = cases
                .filter((c) => !sameOutcome(results[c.name], expected[c.name][era]))
                .map((c) => c.name);
            expect(divergences).toEqual(JAVA_DIVERGENCES[era]);
        });
    }
});
